   this.env.DB.prepare(\"INSERT INTO browser_login_pairings(id,public_code,verifier_digest,user_id,state,created_at_ms,expires_at_ms) VALUES (?,?,?,?,'consumed',?,?)\").bind(id(2+offset),'BCDF-'+(ownerIndex===0?'BCDF':'BCDG'),digest,id(1+offset),current,current+600000),
   this.env.DB.prepare('INSERT INTO web_sessions(id,pairing_id,user_id,token_digest,created_at_ms,fresh_until_ms,idle_expires_at_ms,hard_expires_at_ms) VALUES (?,?,?,?,?,?,?,?)').bind(id(3+offset),id(2+offset),id(1+offset),digest,current,current+600000,current+3600000,current+7776000000),
   this.env.DB.prepare(\"INSERT INTO consent_history(record_type,id,user_id,disclosure_json,disclosure_message_id,decision_message_id,decision_received_at_ms,occurred_at_ms) VALUES ('processing_grant',?,?,'{}','fixture','fixture',?,?)\").bind(id(4+offset),id(1+offset),current,current)
  ]);}return{schemaStatements:schema.length,synthetic:true};});
 if(action==='inspect')return step.do('inspect owned intents',stepConfig,()=>this.env.DB.prepare('SELECT id,status,work_published_at_ms IS NOT NULL AS published,work_last_attempt_at_ms IS NOT NULL AS attempted FROM statement_submissions ORDER BY submitted_at_ms').all().then(r=>r.results));
 if(action==='settle')return step.do('settle synthetic child',stepConfig,async()=>{const env=withErasureRecovery(environment(this.env));await Effect.runPromise(failStatementSubmission({DB:env.DB,userId:event.payload.variant==='cron'?id(1):id(11),submissionId:event.payload.submissionId,reason:'mapping-unavailable'}));return{fixtureTerminalFailure:true};});
 if(action==='cleanup')return step.do('empty owned bucket',stepConfig,async()=>{let count=0;for(;;){const page=await this.env.ERASURE_BUCKET.list({limit:100});if(!page.objects.length)break;await this.env.ERASURE_BUCKET.delete(page.objects.map(o=>o.key));count+=page.objects.length;}return{deletedObjects:count};});
 if(action!=='sample'||!Number.isInteger(event.payload.index)||event.payload.index<0||event.payload.index>=16)throw new Error('Invalid probe');
 return step.do('publish and replay through native User coordinator',stepConfig,async()=>{
  if(!['cron','wake'].includes(event.payload.variant))throw new Error('Invalid variant');const ownerIndex=event.payload.variant==='cron'?0:1,userId=id(1+ownerIndex*10),sessionId=id(3+ownerIndex*10);
  const storage={db:this.env.DB,bucket:this.env.ERASURE_BUCKET};
  const bytes=new TextEncoder().encode('fecha,valor,descripcion\\n2026-10-01,-1000,Synthetic fixture\\n');
  const stagedResponse=await stageOwnedStatement({storage,index:ownerIndex,request:new Request('https://owner-fixture.internal/bytes',{method:'POST',body:bytes})});
  if(stagedResponse.status!==201)throw new Error('Staging refused '+stagedResponse.status);
  const staged=(await stagedResponse.json()).data,idempotencyKey=crypto.randomUUID();
  const published=await publishOwnedStatement({storage,input:{index:ownerIndex,idempotencyKey,reference:staged}});
  if(published.status!==202)throw new Error('Publication refused '+published.status);
  const submission=(await published.json()).data;
  const digest=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(String(ownerIndex+1).repeat(43)))));
  const request=new Request('https://coordinator.internal/call',{method:'POST',headers:{'content-type':'application/json','x-probe-reset':String(event.payload.reset===true),'x-probe-wake':String(event.payload.variant==='wake')},body:JSON.stringify({_tag:'WebSessionWork',userId,sessionId,digest,work:{_tag:'Call',operation:'ingestion.submitForExtraction',input:{payload:{idempotencyKey,reference:staged}}}})});
  const startedAt=Date.now();let responseStatus,diagnostics; 
  try{const response=await this.env.USERS.getByName(userId,{locationHint:'enam'}).fetch(request);responseStatus=response.status;diagnostics={actor:response.headers.get('x-probe-state'),body:await response.json()};}catch{responseStatus='reset';}
  return{index:event.payload.index,variant:event.payload.variant,reset:event.payload.reset===true,submissionId:submission.id,startedAt,responseReceivedAt:Date.now(),responseStatus,diagnostics};
 });
 }
