export class WakeDiscovery extends WorkflowEntrypoint {async run(event,step){const due=await step.do('next five-minute cadence',()=>Math.floor(Date.now()/300000)*300000+300000);await step.sleep('wait for discovery cadence',Math.max(1,due-Date.now()));return step.do('discover committed intents',stepConfig,async()=>{const startedAt=Date.now(),env=withErasureRecovery(environment(this.env));await Effect.runPromise(dispatchStatementExtraction({DB:env.DB,STATEMENT_EXTRACTION_QUEUE:env.OFFERS,STATEMENT_EXTRACTION_WORKFLOW:Option.some(env.CHILD)}));return{due,startedAt,finishedAt:Date.now()};});}}
